6	pub fn short_e(x: f64) -> String {
7	    let s = format!("{:e}", x);
8	    let n = s.split_once('e').unwrap().0.bytes().filter(|c| c.is_ascii_digit()).count();
9	    // (two shortest candidates fit only when 15+ digits are needed)
10	    if n >= 15 {
11	        let t = format!("{:.*e}", n - 1, x);
12	        if t != s && t.parse::<f64>() == Ok(x) {
13	            return t;
14	        }
15	    }
16	    s
17	}
